module keypress_generator(
    input clk,    
    input reset,  
    output reg [9:0] keypress  
);
reg [31:0] counter;
    reg [31:0] index;
    reg [31:0] keypress_array [0:15];
    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            index <= 0;
        end else begin
            if (counter == 20) begin
                counter <= 0;
                index <= index + 1;
                if (index == 15) begin
                    index <= 0;
                end
            end else begin
                counter <= counter + 1;
            end
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            keypress <= 0;
        end else begin
            if (index == 0) begin
                keypress <= keypress_array[0];
            end else if (index == 1) begin
                keypress <= keypress_array[1];
            end else if (index == 2) begin
                keypress <= keypress_array[2];
            end else if (index == 3) begin
                keypress <= keypress_array[3];
            end else if (index == 4) begin
                keypress <= keypress_array[4];
            end else if (index == 5) begin
                keypress <= keypress_array[5];
            end else if (index == 6) begin
                keypress <= keypress_array[6];
            end else if (index == 7) begin
                keypress <= keypress_array[7];
            end else if (index == 8) begin
                keypress <= keypress_array[8];
            end else if (index == 9) begin
                keypress <= keypress_array[9];
            end else if (index == 10) begin
                keypress <= keypress_array[10];
            end else if (index == 11) begin
                keypress <= keypress_array[11];
            end else if (index == 12) begin
                keypress <= keypress_array[12];
            end else if (index == 13) begin
                keypress <= keypress_array[13];
            end else if (index == 14) begin
                keypress <= keypress_array[14];
            end else if (index == 15) begin
                keypress <= keypress_array[15];
            end
        end
    end
    initial begin
        keypress_array[0] = 10'h00;
        keypress_array[1] = 10'h01;
        keypress_array[2] = 10'h02;
        keypress_array[3] = 10'h03;
        keypress_array[4] = 10'h04;
        keypress_array[5] = 10'h05;
        keypress_array[6] = 10'h06;
        keypress_array[7] = 10'h07;
        keypress_array[8] = 10'h08;
        keypress_array[9] = 10'h09;
        keypress_array[10] = 10'h0A;
        keypress_array[11] = 10'h0B;
        keypress_array[12] = 10'h0C;
        keypress_array[13] = 10'h0D;
        keypress_array[14] = 10'h0E;
        keypress_array[15] = 10'h0F;
    end
endmodule

