module submulor_2_stage_unsigned_10_bit(
	input  [9:0] a,
	input  [9:0] b,
	input  [9:0] c,
	input  [9:0] d,
	output [9:0] out,
	input clk);
logic  [19:0] stage0;
	logic  [19:0] stage1;

	always @(posedge clk) begin
	stage0 <= ((d - a) * b) | c;
	stage1 <= stage0;
	end

	assign out = stage1;
endmodule

module addmuladd_1_stage_signed_14_bit_xor_reduction(
	input signed [13:0] a,
	input signed [13:0] b,
	input signed [13:0] c,
	input signed [13:0] d,
	output [13:0] out,
	input clk);
logic signed [27:0] stage0;

	always @(posedge clk) begin
	stage0 <= ((d + a) * b) + c;

	end

	assign out = ^(stage0);
endmodule

module vga_ctrl(
input wire pixel_clk,
output wire hsync,
output wire vsync,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire visible_region
); 

parameter [31:0] total_pixels=640;
parameter [31:0] h_sync_pulses=16;
parameter [31:0] h_blank_pulses=48;
parameter [31:0] v_sync_pulses=10;
parameter [31:0] v_blank_pulses=33;
reg [9:0] h_count;
reg [9:0] v_count;
  assign hsync = h_count[9];
  assign vsync = v_count[9];
  assign pixel_x = h_count[9:0];
  assign pixel_y = v_count[9:0];
  assign visible_region = (h_count[9:0] < total_pixels) && (v_count[9:0] < total_pixels);
  always @(posedge pixel_clk) begin
    if((h_count == (total_pixels - 1))) begin
      h_count <= 0;
      if((v_count == (total_pixels - 1))) begin
        v_count <= 0;
      end
      else begin
        v_count <= v_count + 1;
      end
    end
    else begin
      h_count <= h_count + 1;
    end
  end
endmodule

