module counter
#(
  parameter integer WIDTH=5
 )
 (
  input  wire clk  ,
  input  wire rst  ,
  input  wire load ,
  input  wire enab ,
  input  wire [WIDTH-1:0] cnt_in ,
  output reg  [WIDTH-1:0] cnt_out 
 );
reg [WIDTH-1:0] cnt_tmp;
  always @ (posedge clk or posedge rst)
  begin
    if (rst)
      cnt_out <= 0;
    else if (load)
      cnt_out <= cnt_in;
    else if (enab)
      cnt_out <= cnt_tmp;
    else
      cnt_out <= cnt_out;
  end
  always @ (posedge clk or posedge rst)
  begin
    if (rst)
      cnt_tmp <= 0;
    else if (load)
      cnt_tmp <= cnt_in;
    else if (enab)
      cnt_tmp <= cnt_out + 1;
    else
      cnt_tmp <= cnt_tmp;
  end
endmodule

module comparator (output reg [2:0] result, input [15:0] X, Y, input clk);
always @(posedge clk) begin
        if (X[15] != Y[15]) begin
            if (X[15]) begin
                result <= 3'b100;
            end else begin
                result <= 3'b010;
            end
        end else begin
            if (X[14:10] > Y[14:10]) begin
                result <= 3'b100;
            end else if (X[14:10] < Y[14:10]) begin
                result <= 3'b010;
            end else begin
                if (X[9:0] > Y[9:0]) begin
                    result <= 3'b100;
                end else if (X[9:0] < Y[9:0]) begin
                    result <= 3'b010;
                end else begin
                    result <= 3'b001;
                end
            end
        end
    end
endmodule

