module spdr_uart_framer
(
    input clk_50,
    input rst,

    output reg tx_busy,
    input tx_vld,
    input [7:0] tx_data,

    output rx_vld,
    output [7:0] rx_data,
    output reg rx_frame_error,

    output uart_tx,
    input uart_rx
);
parameter sampling_clk_divider = 100000000 / 115200;

reg [7:0] tx_data_shift_reg;
reg [3:0] tx_data_counter;
reg tx_busy_reg;

always @(posedge clk_50) begin
    if (rst) begin
        tx_data_shift_reg <= 8'h00;
        tx_data_counter <= 4'h0;
        tx_busy_reg <= 1'b0;
    end else begin
        if (tx_vld) begin
            tx_data_shift_reg <= {tx_data_shift_reg[6:0], tx_data[7]};
            tx_data_counter <= tx_data_counter + 1'b1;
            if (tx_data_counter == 4'h7) begin
                tx_busy_reg <= 1'b1;
            end
        end else begin
            tx_busy_reg <= 1'b0;
        end
    end
end

assign uart_tx = tx_busy_reg;

reg [7:0] rx_data_shift_reg;
reg [3:0] rx_data_counter;
reg rx_vld_reg;
reg rx_frame_error_reg;

always @(posedge clk_50) begin
    if (rst) begin
        rx_data_shift_reg <= 8'h00;
        rx_data_counter <= 4'h0;
        rx_vld_reg <= 1'b0;
        rx_frame_error_reg <= 1'b0;
    end else begin
        if (rx_frame_error_reg) begin
            rx_frame_error_reg <= 1'b0;
        end
        if (rx_vld_reg) begin
            if (rx_data_counter == 4'h7) begin
                rx_data_shift_reg <= {rx_data_shift_reg[6:0], uart_rx};
                rx_data_counter <= rx_data_counter + 1'b1;
                if (rx_data_counter == 4'h7) begin
                    rx_vld_reg <= 1'b0;
                end
            end else begin
                rx_data_shift_reg <= {rx_data_shift_reg[6:0], uart_rx};
                rx_data_counter <= rx_data_counter + 1'b1;
            end
        end else begin
            if (rx_data_counter == 4'h7) begin
                rx_data_shift_reg <= {rx_data_shift_reg[6:0], uart_rx};
                rx_data_counter <= rx_data_counter + 1'b1;
                if (rx_data_counter == 4'h7) begin
                    rx_vld_reg <= 1'b1;
                end
            end else begin
                rx_data_shift_reg <= {rx_data_shift_reg[6:0], uart_rx};
                rx_data_counter <= rx_data_counter + 1'b1;
            end
        end
    end
end

assign rx_vld = rx_vld_reg;
assign rx_data = rx_data_shift_reg;

always @(posedge clk_50) begin
    if (rst) begin
        rx_frame_error_reg <= 1'b0;
    end else begin
        if (rx_vld_reg) begin
            if (rx_data_counter == 4'h7) begin
                if (rx_data_shift_reg != 8'h00) begin
                    rx_frame_error_reg <= 1'b1;
                end
            end
        end
    end
end

assign rx_frame_error = rx_frame_error_reg;

endmodule

