output reg clk_o,
output wire [1:0] count_o
); 

reg [1:0] count;
  always @(posedge clk_i) begin
    if(count == 3) begin
      count <= 0;
    end
    else begin
      count <= count + 1;
    end
  end
  assign count_o = count;
  always @(posedge clk_i) begin
    if(count == 0 || count == 1) begin
      clk_o <= 1'b0;
    end
    else begin
      clk_o <= 1'b1;
    end
  end
endmodule

module hardcopyiv_hssi_aux_clock_div (
    clk,     
    reset,   
    enable_d, 
    d,        
    clkout   
);
input clk,reset;
input enable_d;
input [7:0] d;
output clkout;
parameter clk_divide_by = 1;
parameter extra_latency = 0;

reg clkout_tmp;
reg [31:0] count;
reg [7:0] d_tmp;
reg enable_tmp;
reg clk_tmp;
wire [7:0] d_in;
wire enable_in;
wire clk_in;
wire clkout_in;

assign clk_in = clk;
assign enable_in = enable_d;
assign d_in = d;
assign clkout_in = clkout_tmp;

always @(clk_in or d_in or enable_in) begin
    if (reset == 1'b1) begin
        count <= 0;
        clk_tmp <= 0;
        clkout_tmp <= 0;
        d_tmp <= 0;
        enable_tmp <= 0;
    end else begin
        if (enable_in == 1'b1) begin
            if (count == (clk_divide_by - 1)) begin
                clk_tmp <= ~clk_tmp;
                count <= 0;
            end else begin
                count <= count + 1;
            end
            if (d_in != d_tmp) begin
                d_tmp <= d_in;
                count <= 0;
            end
            if (enable_in != enable_tmp) begin
                enable_tmp <= enable_in;
                count <= 0;
            end
        end
        if (clk_in == 1'b1) begin
            clkout_tmp <= clk_tmp;
        end
    end
end

assign clkout = clkout_in;

endmodule

