module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
localparam IDLE = 0, DATA0 = 1, DATA1 = 2;
   reg [1:0] state;
   reg src0_rdy, src1_rdy;
   reg eof;
   wire [35:0] data0, data1;
   assign data0 = data_i & match_mask;
   assign data1 = data_i & ~match_mask;
   assign data0_o = data0;
   assign data1_o = data1;
   assign src0_rdy_o = src0_rdy;
   assign src1_rdy_o = src1_rdy;
   assign dst_rdy_o = dst0_rdy_i | dst1_rdy_i;
   always @(posedge clk) begin
      if (clear) begin
         state <= IDLE;
         src0_rdy <= 0;
         src1_rdy <= 0;
         eof <= 0;
      end else begin
         case (state)
            IDLE: begin
               if (src_rdy_i) begin
                  if (data_i == match_data) begin
                     state <= DATA0;
                     src0_rdy <= 1;
                     src1_rdy <= 0;
                     eof <= 0;
                  end else begin
                     state <= DATA1;
                     src0_rdy <= 0;
                     src1_rdy <= 1;
                     eof <= 0;
                  end
               end
            end
            DATA0: begin
               if (dst0_rdy_i) begin
                  state <= IDLE;
                  src0_rdy <= 0;
                  src1_rdy <= 0;
                  eof <= 0;
               end
            end
            DATA1: begin
               if (dst1_rdy_i) begin
                  state <= IDLE;
                  src0_rdy <= 0;
                  src1_rdy <= 0;
                  eof <= 0;
               end
            end
         endcase
      end
   end
endmodule

module branch_ctrl(
	input [31:0]	data_rs1	,
	input [31:0]	data_rs2	,
	input [2:0]		funct3		,
	output	reg		jmpb
);
always @(*) begin
		case (funct3)
			3'b000: jmpb = (data_rs1 == data_rs2);
			3'b001: jmpb = (data_rs1 != data_rs2);
			3'b010: jmpb = (data_rs1 < data_rs2);
			3'b011: jmpb = (data_rs1 > data_rs2);
			3'b100: jmpb = (data_rs1 < $signed(data_rs2));
			3'b101: jmpb = (data_rs1 > $signed(data_rs2));
		endcase
	end
endmodule

