module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);
reg [3:0] state;
  reg [7:0] data;
  assign io_ready = state == 4'h0;
  assign tx = state == 4'h0 ? 1'b0 : data[0];
  always @(posedge clock) begin
    if (reset) begin
      state <= 4'h0;
      data <= 8'h0;
    end else if (tick) begin
      case (state)
        4'h0: begin
          if (io_valid) begin
            state <= 4'h1;
            data <= io_bits;
          end
        end
        4'h1: begin
          if (io_valid) begin
            state <= 4'h2;
            data <= data >> 1;
          end
        end
        4'h2: begin
          if (io_valid) begin
            state <= 4'h3;
            data <= data >> 1;
          end
        end
        4'h3: begin
          if (io_valid) begin
            state <= 4'h4;
            data <= data >> 1;
          end
        end
        4'h4: begin
          if (io_valid) begin
            state <= 4'h5;
            data <= data >> 1;
          end
        end
        4'h5: begin
          if (io_valid) begin
            state <= 4'h6;
            data <= data >> 1;
          end
        end
        4'h6: begin
          if (io_valid) begin
            state <= 4'h7;
            data <= data >> 1;
          end
        end
        4'h7: begin
          if (io_valid) begin
            state <= 4'h8;
            data <= data >> 1;
          end
        end
        4'h8: begin
          if (io_valid) begin
            state <= 4'h9;
            data <= data >> 1;
          end
        end
        4'h9: begin
          if (io_valid) begin
            state <= 4'hA;
            data <= data >> 1;
          end
        end
        4'hA: begin
          if (io_valid) begin
            state <= 4'hB;
            data <= data >> 1;
          end
        end
        4'hB: begin
          if (io_valid) begin
            state <= 4'hC;
            data <= data >> 1;
          end
        end
        4'hC: begin
          if (io_valid) begin
            state <= 4'hD;
            data <= data >> 1;
          end
        end
        4'hD: begin
          if (io_valid) begin
            state <= 4'hE;
            data <= data >> 1;
          end
        end
        4'hE: begin
          if (io_valid) begin
            state <= 4'hF;
            data <= data >> 1;
          end
        end
        4'hF: begin
          if (io_valid) begin
            state <= 4'h0;
            data <= io_bits;
          end
        end
      endcase
    end
  end
endmodule

