    input wire [31:0]addr,

    input wire [31:0]data,


    input wire we,


    input wire [1:0]access_width
);
reg [31:0]data_reg;

    always @(posedge clk) begin
        if (we) begin
            case (access_width)
                2'b00: data_reg <= data;
                2'b01: data_reg <= {data[7:0], data[15:8], data[23:16], data[31:24]};
                2'b10: data_reg <= {data[15:0], data[31:16]};
                default: data_reg <= data;
            endcase
        end
    end

    always @(posedge clk) begin
        if (we) begin
            case (access_width)
                2'b00: $display("mem_write: %h", data);
                2'b01: $display("mem_write: %h", data[7:0]);
                2'b10: $display("mem_write: %h", data[15:0]);
                default: $display("mem_write: %h", data);
            endcase
        end
    end

endmodule

