module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
); 

reg [6:0] data;
reg [6:0] next_data;
reg [2:0] next_A;
reg next_WR;
reg next_RD;
reg next_CLK;
reg next_RST;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      data <= {7{1'b0}};
      next_data <= {7{1'b0}};
      next_A <= {3{1'b0}};
      next_WR <= 1'b0;
      next_RD <= 1'b0;
      next_CLK <= 1'b0;
      next_RST <= 1'b0;
    end else begin
      data <= next_data;
      next_data <= data;
      next_A <= A;
      next_WR <= WR;
      next_RD <= RD;
      next_CLK <= CLK;
      next_RST <= RST;
    end
  end
  always @(data, next_A, next_WR, next_RD) begin
    if((next_WR == 1'b1)) begin
      next_data <= D;
    end
    else if((next_RD == 1'b1)) begin
      next_data <= data;
    end
    else begin
      next_data <= next_data;
    end
  end
  always @(data, next_A) begin
    if((next_A == 3'b000)) begin
      Y <= {7{1'b0}};
    end
    else begin
      Y <= {1'b0,data};
    end
  end
  assign WCTRL = next_WR;
endmodule

