module vga_controller(
input wire RST,
input wire CLK,
output wire H_SYNC,
output wire V_SYNC,
output wire [10:0] X,
output wire [10:0] Y,
output wire DISP_EN
); 

parameter [31:0] H_ACTIVE=1280;
parameter [31:0] H_FRONT_PORCH=16;
parameter [31:0] H_BACK_PORCH=48;
parameter [31:0] H_SYNC_PULSE=96;
parameter [31:0] H_TOTAL_PIXELS=H_ACTIVE + H_FRONT_PORCH + H_BACK_PORCH + H_SYNC_PULSE;
parameter [31:0] V_ACTIVE=720;
parameter [31:0] V_FRONT_PORCH=10;
parameter [31:0] V_BACK_PORCH=33;
parameter [31:0] V_SYNC_PULSE=2;
parameter [31:0] V_TOTAL_PIXELS=V_ACTIVE + V_FRONT_PORCH + V_BACK_PORCH + V_SYNC_PULSE;
reg [10:0] X_pos = 0;
reg [10:0] Y_pos = 0;
reg H_SYNC = 1'b1;
reg V_SYNC = 1'b1;
reg DISP_EN = 1'b0;
  always @(posedge CLK, posedge RST) begin
    if(RST == 1'b0) begin
      X_pos <= 0;
      Y_pos <= 0;
      H_SYNC <= 1'b1;
      V_SYNC <= 1'b1;
      DISP_EN <= 1'b0;
    end else begin
      if(X_pos == H_TOTAL_PIXELS - 1) begin
        X_pos <= 0;
        if(Y_pos == V_TOTAL_PIXELS - 1) begin
          Y_pos <= 0;
        end
        else begin
          Y_pos <= Y_pos + 1;
        end
      end
      else begin
        X_pos <= X_pos + 1;
      end
      if(X_pos < H_ACTIVE) begin
        H_SYNC <= 1'b1;
      end
      else begin
        H_SYNC <= 1'b0;
      end
      if(Y_pos < V_ACTIVE) begin
        V_SYNC <= 1'b1;
      end
      else begin
        V_SYNC <= 1'b0;
      end
      if(X_pos < H_ACTIVE && Y_pos < V_ACTIVE) begin
        DISP_EN <= 1'b1;
      end
      else begin
        DISP_EN <= 1'b0;
      end
    end
  end
  assign X = X_pos;
  assign Y = Y_pos;
  assign H_SYNC = H_SYNC;
  assign V_SYNC = V_SYNC;
  assign DISP_EN = DISP_EN;
endmodule

