module pingpongmem(clk, rst, wren, rden, address1, address2,
                    datain, dataout, inputsize);
input clk,rst;
input wren, rden;
input [31:0] inputsize;
input [31:0] address1, address2;

input [64*16-1:0] datain;
output reg [16*16-1:0] dataout;
reg [16*16-1:0] datainmem;
reg [16*16-1:0] dataoutmem;
reg [64*16-1:0] datamem [0:64*16-1];

always @(posedge clk) begin
    if (rst) begin
        datainmem <= 0;
        dataoutmem <= 0;
        for (integer i = 0; i < 64*16; i = i + 1) begin
            datamem[i] <= 0;
        end
    end
    else begin
        if (wren) begin
            datamem[address1] <= datain[16*16-1:16*16-inputsize];
            datamem[address1+inputsize] <= datain[16*16-1:16*16];
        end
        if (rden) begin
            dataoutmem <= datamem[address2];
        end
    end
end

always @(datain) begin
    datainmem <= datain[16*16-1:16*16];
end

always @(dataoutmem) begin
    dataout <= dataoutmem[16*16-1:16*16];
end

