   assign CacheHit = 1'b0;
   assign DataOut = (err) ? mem[largest] : DataIn;
   assign Done = ready;
   assign Stall = ~ready;
   assign err = (ready && (Addr[0] == 1'b1));

   initial begin
      loaded = 1'b0;
      largest = 17'b0;
      rand_pat = 32'b0;
