module pipelined_multiplier (a, b, clk, pdt);
input [size-1 : 0] a;
input [size-1 : 0] b;
input clk;
output [2*size-1 : 0] pdt;
parameter size = 16;
parameter level = 3;

reg [size-1 : 0] a_int;
reg [size-1 : 0] b_int;
reg [2*size-1 : 0] pdt_int [0 : level-1];

integer i;

assign pdt = pdt_int[level-1];

always @(posedge clk) begin
    a_int <= a;
    b_int <= b;
    for (i = 0; i < level-1; i = i + 1) begin
        pdt_int[i+1] <= pdt_int[i] * a_int * b_int;
    end
    pdt_int[0] <= a_int * b_int;
end

endmodule

