module multpool_rdata_mux #(
  parameter NBITS     = 256,
  parameter NUM_RDATA = 1024) (
  input  wire               hclk,     
  input  wire               hresetn,  
  input  wire [3*NBITS-1:0] rdata [0 :NUM_RDATA-1],
  input  wire               valid_rd,
  output wire [3*NBITS-1:0] hrdata
);
reg [3*NBITS-1:0] rdata0, rdata1, rdata2, rdata3;
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      rdata0 <= 0;
      rdata1 <= 0;
      rdata2 <= 0;
      rdata3 <= 0;
    end else begin
      if (valid_rd) begin
        rdata0 <= rdata[0];
        rdata1 <= rdata[1];
        rdata2 <= rdata[2];
        rdata3 <= rdata[3];
      end
    end
  end
  reg [3*NBITS-1:0] rdata0_int, rdata1_int, rdata2_int, rdata3_int;
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      rdata0_int <= 0;
      rdata1_int <= 0;
      rdata2_int <= 0;
      rdata3_int <= 0;
    end else begin
      rdata0_int <= rdata0 | rdata1;
      rdata1_int <= rdata2 | rdata3;
      rdata2_int <= rdata0 | rdata1;
      rdata3_int <= rdata2 | rdata3;
    end
  end
  reg [3*NBITS-1:0] rdata0_int2, rdata1_int2, rdata2_int2, rdata3_int2;
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      rdata0_int2 <= 0;
      rdata1_int2 <= 0;
      rdata2_int2 <= 0;
      rdata3_int2 <= 0;
    end else begin
      rdata0_int2 <= rdata0_int | rdata1_int;
      rdata1_int2 <= rdata2_int | rdata3_int;
      rdata2_int2 <= rdata0_int | rdata1_int;
      rdata3_int2 <= rdata2_int | rdata3_int;
    end
  end
  assign hrdata = rdata0_int2 | rdata1_int2 | rdata2_int2 | rdata3_int2;
endmodule

