module uart_send(
  input sys_clk,
  input sys_rst_n,
  input uart_en,
  input [7:0] uart_din,
  output reg uart_txd
);
parameter CLK_FREQ = 100000000;
  parameter UART_BPS = 115200;
  parameter BPS_CNT = CLK_FREQ / UART_BPS - 1;
  reg [1:0] tx_flag;
  reg [7:0] tx_data;
  reg [31:0] clk_cnt;
  reg [3:0] tx_cnt;
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      tx_flag <= 2'b00;
      tx_data <= 8'b00000000;
      clk_cnt <= 0;
      tx_cnt <= 0;
    end else begin
      if (uart_en) begin
        tx_flag <= 2'b01;
        tx_data <= uart_din;
        clk_cnt <= 0;
        tx_cnt <= 0;
      end else begin
        if (tx_flag == 2'b01) begin
          if (clk_cnt == BPS_CNT) begin
            tx_flag <= 2'b10;
            clk_cnt <= 0;
          end else begin
            clk_cnt <= clk_cnt + 1;
          end
        end else if (tx_flag == 2'b10) begin
          if (tx_cnt == 8) begin
            tx_flag <= 2'b11;
            tx_cnt <= 0;
          end else begin
            tx_cnt <= tx_cnt + 1;
          end
        end else if (tx_flag == 2'b11) begin
          if (tx_cnt == 0) begin
            tx_flag <= 2'b00;
            tx_cnt <= 0;
          end else begin
            tx_cnt <= tx_cnt + 1;
          end
        end
      end
    end
  end
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      uart_txd <= 1;
    end else begin
      if (tx_flag == 2'b00) begin
        uart_txd <= 1;
      end else if (tx_flag == 2'b01) begin
        uart_txd <= 0;
      end else if (tx_flag == 2'b10) begin
        uart_txd <= tx_data[0];
        tx_data <= tx_data >> 1;
      end else if (tx_flag == 2'b11) begin
        uart_txd <= 1;
      end
    end
  end
endmodule

