    int i;
    for (i = 0; i < 32; i = i + 1) begin
        mem[i] = 0;
    end
end
always @(posedge clk) begin
    if (MemWrite) begin
        mem[addr] <= write_data;
    end
end
assign read_data = (MemRead) ? mem[addr] : 0;
endmodule

module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    assign enable_wires[0] = ena;
    assign out = cnt;
    assign ovf = (cnt == 2**BITS - 1) ^ updown;
    genvar i;
    generate
        for (i = 0; i < BITS; i = i + 1) begin : gen
            always @(posedge clk or posedge rst) begin
                if (rst) begin
                    cnt[i] <= 1'b0;
                end else if (ena) begin
                    if (updown) begin
                        cnt[i] <= cnt[i] + 1'b1;
                    end else begin
                        cnt[i] <= cnt[i] - 1'b1;
                    end
                end
            end
        end
    endgenerate
endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
reg [31:0] reg1;
		integer i;
		always @ (reg1)
		begin
			for (i = 0; i < 16; i = i + 1)
			begin
				if (reg1[3:0] > 4)
					reg1[3:0] = reg1[3:0] + 3;
				if (reg1[7:4] > 4)
					reg1[7:4] = reg1[7:4] + 3;
				if (reg1[11:8] > 4)
					reg1[11:8] = reg1[11:8] + 3;
				if (reg1[15:12] > 4)
					reg1[15:12] = reg1[15:12] + 3;
				reg1 = reg1 >> 1;
			end
		end
		assign b = reg1[3:0];
		assign s = reg1[7:4];
		assign g = reg1[11:8];
		assign q = reg1[15:12];
endmodule

