module alu
    #(parameter WIDTH = 32)
    (   input  [WIDTH - 1 : 0] a,b,
        input  [2 : 0] m,
        output reg [WIDTH - 1 : 0] y,
        output reg zf,      
        output reg cf,      
        output reg of      
    );
always @(*) begin
        case (m)
            3'b000: y = a + b;
            3'b001: y = a - b;
            3'b010: y = a & b;
            3'b011: y = a | b;
            3'b100: y = a ^ b;
            3'b101: y = a - b;
            3'b110: y = a + b;
            3'b111: y = a ^ b;
        endcase
        if (y == 0) zf = 1'b1;
        else zf = 1'b0;
        if (m[2]) cf = 1'b1;
        else cf = 1'b0;
        of = (a[WIDTH - 1] ^ b[WIDTH - 1] ^ y[WIDTH - 1]) & (a[WIDTH - 1] ^ y[WIDTH - 1]) & (b[WIDTH - 1] ^ y[WIDTH - 1]);
    end
endmodule

