module clk_div(input clk,
					input rst,
					input SW2,
					input SW15,
					input keyReady,
					input [3:0] BTN_OK,
					output reg[31:0]clkdiv,
					output Clk_CPU,
					output reg readn
					);
reg[31:0] counter;
	reg[31:0] step;
	reg auto_clk;
	reg wasReady;
	always @(posedge clk or posedge rst) begin
		if (rst) begin
			counter <= 0;
			step <= 0;
			auto_clk <= 0;
			wasReady <= 0;
		end else begin
			if (keyReady) begin
				if (SW2) begin
					if (counter[24] || counter[4]) begin
						counter <= 0;
						step <= 0;
						auto_clk <= 0;
						wasReady <= 1;
					end else begin
						counter <= counter + 1;
						step <= 0;
						auto_clk <= 0;
						wasReady <= 0;
					end
				end else begin
					if (counter[24] || counter[4]) begin
						counter <= 0;
						step <= 0;
						auto_clk <= 0;
						wasReady <= 1;
					end else begin
						counter <= counter + 1;
						step <= 0;
						auto_clk <= 0;
						wasReady <= 0;
					end
				end
			end
			if (SW15) begin
				if (counter[24] || counter[4]) begin
					counter <= 0;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 1;
				end else begin
					counter <= counter + 1;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 0;
				end
			end
			if (wasReady) begin
				if (BTN_OK[0]) begin
					counter <= 0;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 1;
				end else if (BTN_OK[1]) begin
					counter <= 0;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 1;
				end else if (BTN_OK[2]) begin
					counter <= 0;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 1;
				end else if (BTN_OK[3]) begin
					counter <= 0;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 1;
				end else begin
					counter <= 0;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 1;
				end
			end
		end
	end
	always @(posedge clk or posedge rst) begin
		if (rst) begin
			clkdiv <= 0;
			readn <= 0;
		end else begin
			if (auto_clk) begin
				clkdiv <= counter;
				readn <= 1;
			end else begin
				clkdiv <= 0;
				readn <= 0;
			end
		end
	end
	always @(posedge clk or posedge rst) begin
		if (rst) begin
			auto_clk <= 0;
		end else begin
			if (SW2) begin
				auto_clk <= 1;
			end else begin
				auto_clk <= 0;
			end
		end
	end
endmodule

