module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
reg [31:0] r_count;
  reg [1:0] state;

  assign o_ppfifo_clk = clk;
  assign o_ppfifo_act = {i_ppfifo_rdy[1], i_ppfifo_rdy[0]};
  assign o_ppfifo_stb = (state == READY) ? i_data_en : 1'b0;
  assign o_ppfifo_data = i_rgb;

  always @(posedge clk) begin
    if (rst) begin
      r_count <= 0;
      state <= IDLE;
    end else begin
      case (state)
        IDLE: begin
          if (i_ppfifo_rdy[0] && i_ppfifo_rdy[1]) begin
            state <= READY;
          end
        end
        READY: begin
          if (i_h_blank) begin
            r_count <= r_count + 1;
          end else if (i_v_blank) begin
            state <= RELEASE;
          end else if (r_count == i_ppfifo_size) begin
            state <= RELEASE;
          end else if (i_data_en) begin
            o_ppfifo_stb <= 1'b1;
            o_ppfifo_data <= i_rgb;
            r_count <= r_count + 1;
          end
        end
        RELEASE: begin
          state <= IDLE;
        end
      endcase
    end
  end

  localparam IDLE = 2'b00;
  localparam READY = 2'b01;
  localparam RELEASE = 2'b10;

endmodule

