module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);

 input clock, resetn;
 input [DATA_WIDTH-1:0] i_datain;
 input i_datain_valid;
 output reg o_datain_stall;
 output reg [DATA_WIDTH-1:0] o_dataout;
 input i_dataout_stall;
 output reg o_dataout_valid;
parameter DATA_WIDTH = 32;
 parameter INSERT_REGISTER = 0;

 reg [DATA_WIDTH-1:0] datain;
 reg datain_valid;
 reg datain_stall;
 reg dataout_valid;
 reg dataout_stall;

 always @ (posedge clock or negedge resetn) begin
  if (!resetn) begin
   datain <= 0;
   datain_valid <= 0;
   datain_stall <= 0;
   dataout_valid <= 0;
   dataout_stall <= 0;
  end else begin
   if (INSERT_REGISTER == 1) begin
    if (i_datain_valid) begin
     datain <= i_datain;
     datain_valid <= 1;
     datain_stall <= 0;
    end else begin
     datain_valid <= 0;
     datain_stall <= 1;
    end
    if (i_dataout_stall) begin
     dataout_valid <= 0;
     dataout_stall <= 1;
    end else begin
     dataout_valid <= 1;
     dataout_stall <= 0;
    end
   end else begin
    datain <= i_datain;
    datain_valid <= i_datain_valid;
    datain_stall <= 0;
    dataout_valid <= 1;
    dataout_stall <= 0;
   end
  end
 end

 assign o_datain_stall = datain_stall;
 assign o_dataout = datain;
 assign o_dataout_valid = dataout_valid;

endmodule

