		input start,
		output[3:0] direction,
		output ready
	);
reg[2:0] state;
	assign direction = {state[2],state[1],state[0],state[0]};
	assign ready = (state[2] & state[1] & state[0]);
	always @(posedge clk or posedge start) begin
		if(start) begin
			state <= 3'b000;
		end else begin
			if(state[1:0] == 2'b00) begin
				state <= 3'b001;
			end else if(state[1:0] == 2'b01) begin
				state <= 3'b010;
			end else if(state[1:0] == 2'b10) begin
				state <= 3'b011;
			end else if(state[1:0] == 2'b11) begin
				state <= 3'b100;
			end else begin
				state <= state + 1;
			end
		end
	end
endmodule

