module sparc_ifu_esl_lfsr
(
    input               clk,
    input               rst_n,


    input [15:0]        lfsr_seed,
    input               lfsr_ld,


    input               lfsr_step,


    output reg [15:0]   lfsr_state_f,


    output reg          lfsr_out_f
);
localparam LFSR_WIDTH = 16;
    localparam LFSR_FEEDBACK_TAPS = 16'b00000000000000000000000000000001;

    reg [LFSR_WIDTH-1:0] lfsr_state_n;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            lfsr_state_f <= 16'b0;
        end else begin
            lfsr_state_f <= lfsr_state_n;
        end
    end


    always @(*) begin
        lfsr_state_n = lfsr_state_f;

        lfsr_state_n[LFSR_WIDTH-1] = lfsr_state_f[LFSR_WIDTH-1] ^ LFSR_FEEDBACK_TAPS[LFSR_WIDTH-1];
        lfsr_state_n[LFSR_WIDTH-2:0] = lfsr_state_f[LFSR_WIDTH-2:0] ^ lfsr_state_f[LFSR_WIDTH-1:1];
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            lfsr_out_f <= 1'b0;
        end else begin
            lfsr_out_f <= lfsr_state_f[LFSR_WIDTH-1];
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            lfsr_state_f <= 16'b0;
        end else begin
            if (lfsr_ld) begin
                lfsr_state_f <= lfsr_seed;
            end else if (lfsr_step) begin
                lfsr_state_f <= lfsr_state_n;
            end
        end
    end

endmodule

module mux4_1n (
    input EN_n,
    input A, B,
    input D0, D1, D2, D3,
    output Y
);
reg Y_reg;
    wire [1:0] S = {A, B};
    always @ (D0 or D1 or D2 or D3 or S or EN_n) begin
        if (EN_n == 1'b0) begin
            Y_reg <= 1'b0;
        end else begin
            case (S)
                2'b00: Y_reg <= D0;
                2'b01: Y_reg <= D1;
                2'b10: Y_reg <= D2;
                2'b11: Y_reg <= D3;
            endcase
        end
    end
    assign Y = Y_reg;
endmodule

