module FFlr(
input wire clk,
input wire [31:0] f,
output reg [31:0] g
); 

wire [31:0] len_raw;
wire [31:0] len;
wire [31:0] x_mask;
wire [31:0] incr;
wire [31:0] f_out;
wire [31:0] f_incr;
wire [31:0] f_out_tmp;
wire [31:0] f_incr_tmp;
wire [31:0] f_out_tmp2;
wire [31:0] f_incr_tmp2;
wire [31:0] res;
reg [31:0] f_masked;
reg [31:0] f_incr_tmp3;
reg [31:0] f_out_tmp3;
  assign len_raw = f[30:23] - 255;
  assign len = len_raw[31] == 1'b0 ? len_raw : 256 - len_raw;
  assign x_mask = len[31] == 1'b0 ? len : 32'h80000000;
  assign incr = x_mask[31] == 1'b0 ? 32'h00000001 : 32'h80000001;
  assign f_out = f[31] == 1'b0 ? f : f + incr;
  assign f_incr = f[31] == 1'b0 ? 32'h00000001 : 32'h80000001;
  assign f_out_tmp = f_out[31] == 1'b0 ? f_out : f_out + incr;
  assign f_incr_tmp = f_incr[31] == 1'b0 ? 32'h00000001 : 32'h80000001;
  assign f_out_tmp2 = f_out_tmp[31] == 1'b0 ? f_out_tmp : f_out_tmp + incr;
  assign f_incr_tmp2 = f_incr_tmp[31] == 1'b0 ? 32'h00000001 : 32'h80000001;
  assign f_out_tmp3 = f_out_tmp2[31] == 1'b0 ? f_out_tmp2 : f_out_tmp2 + incr;
  assign f_incr_tmp3 = f_incr_tmp2[31] == 1'b0 ? 32'h00000001 : 32'h80000001;
  assign res = f[31] == 1'b0 ? f[30:23] : f[30:23] + 255;
  always @(posedge clk) begin
    f_masked <= f[31] == 1'b0 ? f : f + incr;
    f_incr_tmp3 <= f_incr_tmp3;
    f_out_tmp3 <= f_out_tmp3;
    g <= f_out_tmp3;
    f_out_tmp2 <= f_out_tmp3;
    f_incr_tmp2 <= f_incr_tmp3;
    f_out_tmp <= f_out_tmp2;
    f_incr_tmp <= f_incr_tmp2;
    f_masked <= f_masked;
  end
endmodule

