module fsm_trafic_light(clk,reset, red,yellow, green);
input clk, reset;

output red,yellow,green;
reg [2:0] state;
reg [2:0] next_state;


always @(posedge clk or posedge reset)
begin
	if (reset)
		state <= 0;
	else
		state <= next_state;
end


always @(*)
begin
	case (state)
		3'b000: next_state = 3'b001;
		3'b001: next_state = 3'b010;
		3'b010: next_state = 3'b011;
		3'b011: next_state = 3'b100;
		3'b100: next_state = 3'b101;
		3'b101: next_state = 3'b110;
		3'b110: next_state = 3'b111;
		3'b111: next_state = 3'b000;
	endcase
end


assign red = (state[2] == 1'b1) ? 1'b1 : 1'b0;
assign yellow = (state[1] == 1'b1) ? 1'b1 : 1'b0;
assign green = (state[0] == 1'b1) ? 1'b1 : 1'b0;
endmodule

