module lpm_or (
    data,  
    result 
);


    input  [(lpm_size * lpm_width)-1:0] data;


    output [lpm_width-1:0] result;
parameter lpm_width = 1;
    parameter lpm_size = 1;


    reg  [lpm_width-1:0] result;
    reg  [lpm_width-1:0] temp;
    integer i, j;


    initial
    begin
        if (lpm_width <= 0)
        begin
            $display("Value of lpm_width parameter must be greater than 0");
            $display("Time: %0t  Instance: %m", $time);
            $finish;
        end


        if (lpm_size <= 0)
        begin
            $display("Value of lpm_size parameter must be greater than 0");
            $display("Time: %0t  Instance: %m", $time);
            $finish;
        end
    end


    always @ (data)
    begin
        for (i = 0; i < lpm_width; i = i + 1)
        begin
            temp[i] = 0;
            for (j = 0; j < lpm_size; j = j + 1)
            begin
                temp[i] = temp[i] | data[(j * lpm_width) + i];
            end
        end
    end


    assign result = temp;
