module APB_master(input Transfer,              
                  input Wr_Rd,                 
                  input [4:0] Address,         
                  input [31:0] write_data,     
                  output reg [31:0] read_data, 
                  input PCLK,                  
                  input PRESETn,               
                  input PREADY,                
                  input [31:0] PRDATA,         
                  input PSLVERR,               
                  output reg [4:0] PADDR,      
                  output reg PSELx,            
                  output reg PENABLE,          
                  output reg PWRITE,           
                  output reg [31:0] PWDATA);
parameter IDLE = 2'b00, SETUP = 2'b01, ACCESS = 2'b10;
  reg [1:0] state, next_state;
  always @(posedge PCLK or negedge PRESETn) begin
    if (!PRESETn) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end
  always @(*) begin
    next_state = state;
    case (state)
      IDLE: begin
        if (Transfer) begin
          next_state = SETUP;
        end
      end
      SETUP: begin
        if (PREADY) begin
          next_state = ACCESS;
        end
      end
      ACCESS: begin
        if (PSLVERR) begin
          next_state = IDLE;
        end
        else if (PREADY) begin
          if (Wr_Rd) begin
            PSELx = 1'b1;
            PENABLE = 1'b1;
            PWRITE = 1'b1;
            PWDATA = write_data;
            PADDR = Address;
          end
          else begin
            PSELx = 1'b1;
            PENABLE = 1'b1;
            PWRITE = 1'b0;
            PWDATA = PRDATA;
            PADDR = Address;
          end
          next_state = IDLE;
        end
      end
      default: begin
        next_state = IDLE;
      end
    endcase
  end
  always @(posedge PCLK or negedge PRESETn) begin
    if (!PRESETn) begin
      PSELx <= 1'b0;
      PENABLE <= 1'b0;
      PWRITE <= 1'b0;
      PWDATA <= 32'b0;
      PADDR <= 5'b0;
    end else begin
      case (state)
        IDLE: begin
          PSELx <= 1'b0;
          PENABLE <= 1'b0;
          PWRITE <= 1'b0;
          PWDATA <= 32'b0;
          PADDR <= 5'b0;
        end
        SETUP: begin
          PSELx <= 1'b0;
          PENABLE <= 1'b0;
          PWRITE <= 1'b0;
          PWDATA <= 32'b0;
          PADDR <= 5'b0;
        end
        ACCESS: begin
          PSELx <= 1'b1;
          PENABLE <= 1'b1;
          PWRITE <= 1'b0;
          PWDATA <= PRDATA;
          PADDR <= Address;
        end
        default: begin
          PSELx <= 1'b0;
          PENABLE <= 1'b0;
          PWRITE <= 1'b0;
          PWDATA <= 32'b0;
          PADDR <= 5'b0;
        end
      endcase
    end
  end
  always @(posedge PCLK or negedge PRESETn) begin
    if (!PRESETn) begin
      read_data <= 32'b0;
    end else begin
      case (state)
        IDLE: begin
          read_data <= 32'b0;
        end
        ACCESS: begin
          if (Wr_Rd) begin
            read_data <= write_data;
          end
          else begin
            read_data <= PRDATA;
          end
        end
        default: begin
          read_data <= 32'b0;
        end
      endcase
    end
  end
endmodule

