module cyclonev_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg mainclk_tmp;
reg updateclk_tmp;
reg capture_tmp;
reg update_tmp;

always @ (captnupdt or shiftnld or clk)
    begin
        case ({captnupdt, shiftnld, clk})
            3'b000: {mainclk_tmp, updateclk_tmp, capture_tmp, update_tmp} = 4'b0000;
            3'b001: {mainclk_tmp, updateclk_tmp, capture_tmp, update_tmp} = 4'b0001;
            3'b010: {mainclk_tmp, updateclk_tmp, capture_tmp, update_tmp} = 4'b0010;
            3'b011: {mainclk_tmp, updateclk_tmp, capture_tmp, update_tmp} = 4'b0011;
            3'b100: {mainclk_tmp, updateclk_tmp, capture_tmp, update_tmp} = 4'b0100;
            3'b101: {mainclk_tmp, updateclk_tmp, capture_tmp, update_tmp} = 4'b0101;
            3'b110: {mainclk_tmp, updateclk_tmp, capture_tmp, update_tmp} = 4'b0110;
            3'b111: {mainclk_tmp, updateclk_tmp, capture_tmp, update_tmp} = 4'b0111;
        endcase
    end

assign mainclk = mainclk_tmp & 1'b1;
assign updateclk = updateclk_tmp & 1'b1;
assign capture = capture_tmp & 1'b1;
assign update = update_tmp & 1'b1;

endmodule

