module uart_tx_tester ( input clk_50M, input run_test_raw, input tx_busy, output reg [7:0] data_out, output reg trigger );
parameter MSG_DELAY = 100000000; 
parameter STATE_LOAD = 0; 
parameter STATE_TRIGGER = 1; 
parameter STATE_BUSY = 2; 
parameter STATE_POLL = 3; 
parameter STATE_PAUSE = 4; 
reg [1:0] state; 
reg [7:0] data_pos; 
reg [31:0] delay; 
always @(posedge clk_50M) begin 
    if (run_test_raw) begin 
        state <= STATE_LOAD; 
        data_pos <= 0; 
        delay <= 0; 
    end 
    else begin 
        case (state) 
            STATE_LOAD: begin 
                if (data_pos == 0) begin 
                    data_out <= "Hello World! "; 
                    data_pos <= data_pos + 1; 
                end 
                else begin 
                    state <= STATE_TRIGGER; 
                end 
            end 
            STATE_TRIGGER: begin 
                trigger <= 1; 
                delay <= delay + 1; 
                if (delay == MSG_DELAY) begin 
                    state <= STATE_BUSY; 
                end 
            end 
            STATE_BUSY: begin 
                if (tx_busy) begin 
                    state <= STATE_POLL; 
                end 
                else begin 
                    state <= STATE_PAUSE; 
                end 
            end 
            STATE_POLL: begin 
                if (tx_busy) begin 
                    state <= STATE_BUSY; 
                end 
                else begin 
                    state <= STATE_PAUSE; 
                end 
            end 
            STATE_PAUSE: begin 
                if (tx_busy) begin 
                    state <= STATE_BUSY; 
                end 
                else begin 
                    state <= STATE_LOAD; 
                end 
            end 
        endcase 
    end 
end 
endmodule

