module KEY_MUX
(
	input PS2_CLK,
	input PS2_DAT,
	output [9:0]LEDR,
	output [6:0]HEX0,
	output [6:0]HEX1
);
wire [7:0]scan_code;
	reg [3:0]S,NS;
	reg [7:0]in1,in2,in3,out;
	assign LEDR[3:0]=S;
	assign LEDR[9:4]=NS;
	assign HEX0=in1;
	assign HEX1=in2;
	assign HEX1=out;
	assign HEX0=scan_code;
	assign HEX1=scan_code;
	assign scan_code=scan_code;
	always @(posedge PS2_CLK)
	begin
		S<=NS;
		case(S)
			4'b0000:begin
				in1<=8'b0;
				in2<=8'b0;
				in3<=8'b0;
				out<=8'b0;
				NS<=4'b0001;
			end
			4'b0001:begin
				in1<=in1;
				in2<=in2;
				in3<=in3;
				out<=in3;
				NS<=4'b0010;
			end
			4'b0010:begin
				in1<=in1;
				in2<=in2;
				in3<=in3;
				out<=in3;
				NS<=4'b0011;
			end
			4'b0011:begin
				in1<=in1;
				in2<=in2;
				in3<=in3;
				out<=in3;
				NS<=4'b0100;
			end
			4'b0100:begin
				in1<=in1;
				in2<=in2;
				in3<=in3;
				out<=in3;
				NS<=4'b0000;
			end
			default:begin
				in1<=8'b0;
				in2<=8'b0;
				in3<=8'b0;
				out<=8'b0;
				NS<=4'b0000;
			end
		endcase
	end
	KEY keyboard(
		.PS2_CLK(PS2_CLK),
