module hardcopyiv_ram_register (
                             d,
                             clk,
                             aclr,
                             devclrn,
                             devpor,
                             stall,
                             ena,
                             q,
                             aclrout
                            );  

input [width - 1:0] d;    
input clk;                
input aclr;               
input devclrn,devpor;     
input stall; 
input ena;                
output [width - 1:0] q;   
output aclrout;
parameter width = 16;     
parameter depth = 1;      

reg [width - 1:0] ram;     
reg [width - 1:0] q_reg;   
reg aclrout;               

specify
    (posedge clk => (q +: q_reg)) = (0, 0);
    (posedge aclr => (q +: q_reg)) = (0, 0);
    (posedge devclrn => (q +: q_reg)) = (0, 0);
    (posedge devpor => (q +: q_reg)) = (0, 0);
endspecify

always @(posedge clk or posedge aclr or posedge devclrn or posedge devpor)
    if (devclrn === 1'b0 || devpor === 1'b0)
        aclrout <= 1'b0;
    else if (aclr === 1'b1)
        aclrout <= 1'b1;
    else if (ena === 1'b1)
        ram <= d;
    else if (stall === 1'b0)
        ram <= q_reg;

always @(posedge clk or posedge aclr or posedge devclrn or posedge devpor)
    if (devclrn === 1'b0 || devpor === 1'b0)
        q_reg <= 0;
    else if (aclr === 1'b1)
        q_reg <= 0;
    else if (ena === 1'b1)
        q_reg <= ram;

assign q = q_reg;

endmodule

