module datapath(clk, startGameEn, user_x, user_y, enemy_x, enemy_y, enem_grid, x, y, colour);
input clk; 
	input startGameEn; 
	input [7:0]user_x; 
	input [6:0]user_y; 
	input [7:0]enemy_x; 
	input [6:0]enemy_y; 
	input [160*120-1:0] enem_grid; 
	output reg [7:0] x; 
	output reg [6:0] y; 
	output reg[2:0] colour;
reg clear;
	always @(posedge clk) begin
		if (startGameEn) begin
			x <= 0;
			y <= 0;
			clear <= 1;
		end
		else begin
			if (clear) begin
				x <= 0;
				y <= 0;
				clear <= 0;
			end
			else begin
				if (x == 160 && y == 120) begin
					x <= 0;
					y <= 0;
				end
				else begin
					if (x == user_x && y == user_y) begin
						colour <= 3;
					end
					else if (x == enemy_x && y == enemy_y) begin
						colour <= 2;
					end
					else if (enem_grid[160*y + x] == 1) begin
						colour <= 4;
					end
					else begin
						colour <= 0;
					end
					x <= x + 1;
					y <= y + 1;
				end
			end
		end
	end
endmodule

module Start_UP_Handler(
input wire i_CLK,
output wire o_RST
); 

parameter [31:0] g_Clock_Frequency=100000000;
parameter [31:0] g_Initial_Reset_Time=1000000;
reg r_RST = 1'b1;
reg [31:0] r_RST_Counter = 0;
  assign o_RST = r_RST;
  always @(posedge i_CLK) begin
    if(r_RST == 1'b1) begin
      r_RST_Counter <= 0;
    end
    else if(r_RST_Counter == (g_Clock_Frequency * g_Initial_Reset_Time) - 1) begin
      r_RST <= 1'b0;
    end
    else begin
      r_RST_Counter <= r_RST_Counter + 1;
    end
  end
endmodule

