			registers[29] <= 32'b0;
			registers[30] <= 32'b0;
			registers[31] <= 32'b0;
		end
		else
		begin
			if (regwrite)
			begin
				if (of_control == 2'b00)
					registers[wrreg] <= wrdata;
				else if (of_control == 2'b01)
					registers[wrreg] <= wrdata[31:0];
				else if (of_control == 2'b10)
					registers[wrreg] <= wrdata[31:0];
				else if (of_control == 2'b11)
					registers[wrreg] <= wrdata[31:0];
			end
		end
	end

	always @(read1 or read2)
	begin
		if (read1 == 5'b00000)
			data1 <= 32'b0;
		else
			data1 <= registers[read1];
		if (read2 == 5'b00000)
			data2 <= 32'b0;
		else
			data2 <= registers[read2];
	end
