	log2 log2Baud(log2Baud, Baud);
	log2 log2Oversampling(log2Oversampling, Oversampling);
	
	log2 log2Acc(log2Acc, log2ClkFrequency + log2Baud + log2Oversampling);
	
	reg [log2Acc:0] Acc;
