module db (
        input clk, n_reset, button_in,
        output reg out
    );
parameter maxbit = 10;
    reg [maxbit-1:0] q_reg, q_next;
    reg f1, f2;
    wire q_add, q_reset;
    assign q_add = ~q_reg[maxbit-1] & q_reg[maxbit-2:0];
    assign q_reset = q_reg[maxbit-1] & ~q_reg[maxbit-2:0];
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_reg <= 0;
        end else begin
            q_reg <= q_next;
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            f1 <= 0;
            f2 <= 0;
        end else begin
            f1 <= button_in;
            f2 <= f1;
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_next <= 0;
        end else begin
            if (q_reset) begin
                q_next <= 0;
            end else begin
                if (q_add) begin
                    q_next <= q_reg + 1;
                end else begin
                    q_next <= q_reg;
                end
            end
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            out <= 0;
        end else begin
            if (q_reg == 2**maxbit-1) begin
                out <= f2;
            end else begin
                out <= 0;
            end
        end
    end
endmodule

