      sNEXT_STATE <= A_WIN;
    end
    default : begin
      sNEXT_STATE <= DRAW;
    end
    endcase
  end
  assign sWIN = sSTATE;
  assign oA = sWIN[0];
  assign oB = sWIN[1];
