module pipeline(input  wire       init,
		output wire [3:0] d,
		output wire       dk);
wire [3:0] d1, d2, d3;
wire       dk1, dk2, dk3;
wire       drot;

assign drot = d[3] ^ d[2] ^ d[1] ^ d[0];

pipeline_stage #(.DELAY(9)) stage1(.init(init), .d(d1), .dk(dk1));
pipeline_stage #(.DELAY(9)) stage2(.init(init), .d(d2), .dk(dk2));
pipeline_stage #(.DELAY(9)) stage3(.init(init), .d(d3), .dk(dk3));

assign d = drot;
assign dk = dk3;

endmodule

module mulor_3_stage_unsigned_10_bit(
	input  [9:0] a,
	input  [9:0] b,
	input  [9:0] c,
	output [9:0] out,
	input clk);
logic  [19:0] stage0;
	logic  [19:0] stage1;
	logic  [19:0] stage2;

	always @(posedge clk) begin
	stage0 <= (a * b) | c;
	stage1 <= stage0;
	stage2 <= stage1;
	end

	assign out = stage2;
endmodule

