module alu_control (alu_op, func, alu_ctrl);
input [2:0] alu_op;
    input [2:0] func;
    output [2:0] alu_ctrl;
wire not_alu_op0, not_alu_op1, not_alu_op2;
    wire not_func0, not_func1, not_func2;
    not not1 (not_alu_op0, alu_op[0]);
    not not2 (not_alu_op1, alu_op[1]);
    not not3 (not_alu_op2, alu_op[2]);
    not not4 (not_func0, func[0]);
    not not5 (not_func1, func[1]);
    not not6 (not_func2, func[2]);
    and and1 (alu_ctrl[0], not_alu_op0, not_alu_op1, not_alu_op2);
    and and2 (alu_ctrl[1], not_alu_op0, not_alu_op1, func[2]);
    and and3 (alu_ctrl[2], not_alu_op0, func[1], not_func2);
    or or1 (alu_ctrl[0], alu_ctrl[1], alu_ctrl[2]);
endmodule

