module bus_mux (din,sel,dout);

input [TOTAL_DAT-1 : 0] din;
input [SEL_WIDTH-1:0] sel;
output [DAT_WIDTH-1:0] dout;
parameter DAT_WIDTH = 32;
parameter SEL_WIDTH = 2;
parameter TOTAL_DAT = 1 << SEL_WIDTH;

wire [DAT_WIDTH-1:0] temp [0:TOTAL_DAT-1];

genvar i;
generate
	for (i = 0; i < TOTAL_DAT; i = i + 1) begin
		assign temp[i] = din[i*DAT_WIDTH +: DAT_WIDTH];
	end
endgenerate

genvar j;
generate
	for (j = 0; j < SEL_WIDTH; j = j + 1) begin
		assign dout[j*DAT_WIDTH +: DAT_WIDTH] = temp[sel[j]];
	end
endgenerate

endmodule

