module NBitCounterChain #(
   parameter counterSize   = 16,
   parameter numOfCounters = 3054
) (
   input  wire                   clk,
   input  wire                   reset,
   output wire [counterSize-1:0] outCount
);
reg [counterSize-1:0] counts[numOfCounters-1:0];
   reg [counterSize-1:0] terminalCounts[numOfCounters-1:0];
   wire [counterSize-1:0] enable;
   assign enable = terminalCounts[numOfCounters-2];
   genvar i;
   generate
      for (i = 0; i < numOfCounters; i = i + 1) begin : genCounters
         NBitCounter #(
            .counterSize(counterSize)
         ) counter (
            .clk(clk),
            .reset(reset),
            .count(counts[i]),
            .enable(enable),
            .outCount(counts[i+1])
         );
         assign terminalCounts[i] = counts[i] == (2**counterSize-1) ? 1'b1 : 1'b0;
      end
   endgenerate
   assign outCount = counts[numOfCounters-1];
endmodule

