module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
); 

parameter [31:0] h_size=640;
parameter [31:0] v_size=480;
parameter [31:0] h_front=16;
parameter [31:0] h_back=48;
parameter [31:0] h_retrace=96;
parameter [31:0] v_front=10;
parameter [31:0] v_back=2;
parameter [31:0] v_retrace=33;
reg [9:0] h_count_reg;
reg [9:0] v_count_reg;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      h_count_reg <= {10{1'b0}};
      v_count_reg <= {10{1'b0}};
      active <= 1'b0;
      hsync <= 1'b1;
      vsync <= 1'b1;
    end else begin
      h_count_reg <= h_count_reg + 1;
      v_count_reg <= v_count_reg + 1;
      if((h_count_reg == (h_size + h_front + h_back + h_retrace))) begin
        h_count_reg <= {10{1'b0}};
        if((v_count_reg == (v_size + v_front + v_back + v_retrace))) begin
          v_count_reg <= {10{1'b0}};
        end
        else begin
          v_count_reg <= v_count_reg + 1;
        end
      end
      if((h_count_reg < (h_size + h_front))) begin
        hsync <= 1'b0;
      end
      else begin
        hsync <= 1'b1;
      end
      if((v_count_reg < (v_size + v_front))) begin
        vsync <= 1'b0;
      end
      else begin
        vsync <= 1'b1;
      end
      if((h_count_reg < (h_size + h_front)) && (v_count_reg < (v_size + v_front))) begin
        active <= 1'b1;
      end
      else begin
        active <= 1'b0;
      end
    end
  end
  assign xaddr = h_count_reg;
  assign yaddr = v_count_reg;
endmodule

