    localparam [2:0] B = 3'b001;
    localparam [2:0] C = 3'b010;
    localparam [2:0] D = 3'b011;
    localparam [2:0] E = 3'b100;
    localparam [2:0] F = 3'b101;
    localparam [2:0] G = 3'b110;
    localparam [2:0] H = 3'b111;
    reg [2:0] state;
    always @(posedge clk) begin
        if (areset) begin
            state <= A;
        end else begin
            case (state)
                A: begin
                    if (x) begin
                        state <= B;
                    end else begin
                        state <= A;
                    end
                end
                B: begin
                    if (x) begin
                        state <= B;
                    end else begin
                        state <= A;
                    end
                end
                default: begin
                    state <= A;
                end
            endcase
        end
    end
    assign z = state[0];
endmodule

