module TopModule(
input wire clk,
input wire x,
input wire [2:0] y,
output wire Y0,
output wire z
); 

wire [2:0] Y;
wire [2:0] nextY;
  assign Y[0] = nextY[0];
  assign Y[1] = nextY[1];
  assign Y[2] = nextY[2];
  assign Y0 = Y[0];
  assign z = Y[2];
  always @(Y, x) begin
    case(Y)
    3'b000 : begin
      if((x == 1'b0)) begin
        nextY <= 3'b000;
      end
      else begin
        nextY <= 3'b001;
      end
    end
    3'b001 : begin
      if((x == 1'b0)) begin
        nextY <= 3'b001;
      end
      else begin
        nextY <= 3'b100;
      end
    end
    3'b010 : begin
      if((x == 1'b0)) begin
        nextY <= 3'b010;
      end
      else begin
        nextY <= 3'b001;
      end
    end
    3'b011 : begin
      if((x == 1'b0)) begin
        nextY <= 3'b001;
      end
      else begin
        nextY <= 3'b010;
      end
    end
    3'b100 : begin
      if((x == 1'b0)) begin
        nextY <= 3'b011;
      end
      else begin
        nextY <= 3'b100;
      end
    end
    default : begin
      nextY <= 3'b000;
    end
    endcase
  end
endmodule

