module TopModule(
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);
reg state;
    reg f_reg;
    reg g_reg;
    always @(posedge clk) begin
        if (resetn == 1'b0) begin
            state <= 'b0;
            f_reg <= 'b0;
            g_reg <= 'b0;
        end else begin
            case (state)
                'b0: begin
                    f_reg <= 'b0;
                    g_reg <= 'b0;
                    if (x == 1'b1) begin
                        state <= 'b1;
                    end
                end
                'b1: begin
                    f_reg <= 'b1;
                    g_reg <= 'b1;
                    if (x == 1'b1) begin
                        state <= 'b2;
                    end
                    else if (x == 1'b0) begin
                        state <= 'b1;
                    end
                end
                'b2: begin
                    f_reg <= 'b1;
                    g_reg <= 'b1;
                    if (y == 1'b1) begin
                        state <= 'b3;
                    end
                    else begin
                        state <= 'b2;
                    end
                end
                'b3: begin
                    f_reg <= 'b1;
                    g_reg <= 'b1;
                    if (y == 1'b1) begin
                        state <= 'b3;
                    end
                    else begin
                        state <= 'b4;
                    end
                end
                'b4: begin
                    f_reg <= 'b1;
                    g_reg <= 'b0;
                    if (y == 1'b1) begin
                        state <= 'b3;
                    end
                    else begin
                        state <= 'b4;
                    end
                end
                default: begin
                    state <= 'b0;
                    f_reg <= 'b0;
                    g_reg <= 'b0;
                end
            endcase
        end
    end
    assign f = f_reg;
    assign g = g_reg;
endmodule

module TopModule(
    input  clk,
    input  reset,
    input  ena,
    output pm,
    output [7:0] hh,
    output [7:0] mm,
    output [7:0] ss
);
reg [3:0] h;
    reg [3:0] m;
    reg [3:0] s;
    reg pm;
    always @(posedge clk) begin
        if (ena) begin
            h <= h + 1;
            if (h == 12) begin
                h <= 0;
                pm <= ~pm;
            end
        end
        if (reset) begin
            h <= 0;
            m <= 0;
            s <= 0;
            pm <= 0;
        end
    end
    always @(posedge clk) begin
        if (ena) begin
            m <= m + 1;
            if (m == 59) begin
                m <= 0;
                s <= s + 1;
                if (s == 59) begin
                    s <= 0;
                end
            end
        end
        if (reset) begin
            m <= 0;
            s <= 0;
        end
    end
    always @(posedge clk) begin
        if (ena) begin
            s <= s + 1;
            if (s == 59) begin
                s <= 0;
            end
        end
        if (reset) begin
            s <= 0;
        end
    end
    assign hh = h;
    assign mm = m;
    assign ss = s;
    assign pm = pm;
endmodule

