  assign Y4 = {y[4:0], ~w};
  always @(Y2 or Y4) begin
    case (y[5:0])
      6'b000001: y <= Y2;
      6'b000010: y <= Y4;
      6'b000100: y <= Y2;
      6'b001000: y <= Y4;
      6'b010000: y <= Y2;
      6'b100000: y <= Y4;
    endcase
  end
