module TopModule (
  input clk,
  input in,
  input reset,
  output out
);
reg [1:0] state;
  reg [1:0] next_state;
  reg out_tmp;
  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
    end else begin
      state <= next_state;
    end
  end
  always @(state, in) begin
    case (state)
      2'b00: begin
        if (in) begin
          next_state = 2'b01;
        end else begin
          next_state = 2'b00;
        end
      end
      2'b01: begin
        if (in) begin
          next_state = 2'b01;
        end else begin
          next_state = 2'b10;
        end
      end
      2'b10: begin
        if (in) begin
          next_state = 2'b10;
        end else begin
          next_state = 2'b11;
        end
      end
      2'b11: begin
        if (in) begin
          next_state = 2'b10;
        end else begin
          next_state = 2'b11;
        end
      end
      default: begin
        next_state = 2'b00;
      end
    endcase
  end
  always @(state) begin
    case (state)
      2'b00: begin
        out_tmp = 1'b0;
      end
      2'b01: begin
        out_tmp = 1'b0;
      end
      2'b10: begin
        out_tmp = 1'b0;
      end
      2'b11: begin
        out_tmp = 1'b1;
      end
      default: begin
        out_tmp = 1'b0;
      end
    endcase
  end
  assign out = out_tmp;
endmodule

module TopModule (
  input clk,
  input reset,
  input x,
  output reg z
);
reg [2:0] y;
  always @(posedge clk) begin
    if (reset) begin
      y <= 3'b000;
    end else begin
      case (y)
        3'b000: begin
          if (x) begin
            y <= 3'b001;
          end else begin
            y <= 3'b000;
          end
        end
        3'b001: begin
          if (x) begin
            y <= 3'b100;
          end else begin
            y <= 3'b001;
          end
        end
        3'b010: begin
          if (x) begin
            y <= 3'b010;
          end else begin
            y <= 3'b001;
          end
        end
        3'b011: begin
          if (x) begin
            y <= 3'b001;
          end else begin
            y <= 3'b010;
          end
        end
        3'b100: begin
          if (x) begin
            y <= 3'b011;
          end else begin
            y <= 3'b100;
          end
        end
      endcase
    end
  end
  always @(y) begin
    case (y)
      3'b000: z <= 1'b0;
      3'b001: z <= 1'b0;
      3'b010: z <= 1'b0;
      3'b011: z <= 1'b1;
      3'b100: z <= 1'b1;
    endcase
  end
endmodule

