      3'b001: begin
        next_state = 3'b010;
      end
      3'b010: begin
        next_state = 3'b011;
      end
      3'b011: begin
        next_state = 3'b000;
      end
      default: begin
        next_state = 3'b000;
      end
    endcase
  end
  always @(posedge clk) begin
    if (resetn == 1'b0) begin
      g0 <= 1'b0;
      g1 <= 1'b0;
      g2 <= 1'b0;
    end else begin
      case (state)
        3'b000: begin
